import { z } from 'zod';

// Content generated by Gemini for skills, validated before it is stored.
// Field descriptions are sent with the JSON schema: keep them precise.

const codeBlock = z.object({
  lang: z
    .string()
    .trim()
    .max(30)
    .describe(
      'Language of the code for highlighting: css, html, javascript, typescript, tsx, python, sql, c, cpp, shellscript, docker, php, prisma'
    ),
  code: z
    .string()
    .max(4000)
    .describe('Correct, idiomatic code for current versions, no line numbers'),
});

// "Fiche mémo" of a roadmap notion: a quick reminder to reread during a project.
export const notionSheetSchema = z.object({
  summary: z
    .string()
    .trim()
    .min(1)
    .max(800)
    .describe('2 to 3 sentences in plain French, what it is and when to use it'),
  syntax: codeBlock.describe('The minimal syntax, a few lines'),
  example: codeBlock.describe(
    'One realistic example, ideally about expenses, job applications or habits, with short French comments'
  ),
  pitfalls: z
    .array(z.string().trim().min(1).max(300))
    .min(1)
    .max(4)
    .describe('2 to 4 common mistakes, in French, one sentence each'),
  docUrl: z
    .string()
    .trim()
    .max(300)
    .describe('Official documentation URL (MDN, python.org, postgresql.org…), empty if unsure'),
});

export type NotionSheet = z.infer<typeof notionSheetSchema>;

// What Gemini returns for a sheet: the sheet plus names of related reference entries.
export const notionSheetAnswerSchema = notionSheetSchema.extend({
  related: z
    .array(z.string().trim().max(120))
    .max(5)
    .describe(
      'Up to 5 exact names of reference entries related to this notion, e.g. "Array.prototype.map", "justify-content", "git rebase"'
    ),
});

export const referenceDetailsSchema = z.object({
  description: z.string().trim().min(1).max(1000).describe('2 to 4 sentences in French'),
  syntax: z.string().max(1000).describe('Syntax or signature, empty if not relevant'),
  values: z
    .array(z.string().trim().max(80))
    .max(16)
    .describe('Common values or options (CSS values, flags…), empty if none'),
  example: codeBlock.describe('A short realistic example'),
  equivalents: z
    .array(z.string().trim().max(80))
    .max(10)
    .describe('Tailwind classes for a CSS property, or other close equivalents; empty if none'),
});

export type ReferenceDetails = z.infer<typeof referenceDetailsSchema>;

export const referenceEntryAnswerSchema = referenceDetailsSchema.extend({
  summary: z
    .string()
    .trim()
    .min(1)
    .max(120)
    .describe('One short line in French for the list, e.g. "Alignement sur l’axe principal"'),
});

// "Générer la roadmap": notions per level, junior (1) to senior (5).
export const roadmapAnswerSchema = z.object({
  levels: z
    .array(
      z.object({
        level: z.number().int().min(1).max(5),
        title: z
          .string()
          .trim()
          .min(1)
          .max(80)
          .describe('Short French title of the level, e.g. "Tableaux, objets et DOM"'),
        notions: z
          .array(z.string().trim().min(1).max(120))
          .min(3)
          .max(8)
          .describe('Notions in learning order, short French labels'),
      })
    )
    .length(5),
});

export const REFERENCE_KINDS = [
  'ELEMENT',
  'ATTRIBUTE',
  'PROPERTY',
  'AT_RULE',
  'SELECTOR',
  'FUNCTION',
  'METHOD',
  'OBJECT',
  'KEYWORD',
  'TYPE',
  'COMMAND',
  'CLASS',
  'HOOK',
  'OTHER',
] as const;

// "Générer la référence" for skills without an MDN source.
export const referenceListAnswerSchema = z.object({
  entries: z
    .array(
      z.object({
        name: z
          .string()
          .trim()
          .min(1)
          .max(120)
          .describe('Exact name as written in code or a terminal'),
        kind: z.enum(REFERENCE_KINDS),
        group: z.string().trim().min(1).max(60).describe('French category label'),
        summary: z.string().trim().min(1).max(120).describe('One short line in French'),
        isCommon: z.boolean().describe('True for what a junior developer uses every week'),
      })
    )
    .min(20)
    .max(250),
});

export function parseNotionSheet(value: unknown): NotionSheet | null {
  const result = notionSheetSchema.safeParse(value);
  return result.success ? result.data : null;
}

export function parseReferenceDetails(value: unknown): ReferenceDetails | null {
  const result = referenceDetailsSchema.safeParse(value);
  return result.success ? result.data : null;
}
